# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/ch3_pipeline_restored/scripts/64u_career_orientation_split_1979_2019.R
# 64u_career_orientation_split_1979_2019.R
#
# Rebuilds the backbench/frontbench self-regarding split (64q) with a
# REDESIGNED dictionary. PJ, 11 Sep: 64q's "career_terms" turned out to be
# almost entirely office-reference language ("my department", "as Secretary
# of State") that fires mechanically off HOLDING a role - of its 18 terms,
# 17 are office-reference, only "my career" reflects orientation rather
# than office. That's the same "institutionally normal, not evidence of
# self-regard" problem the backbench/frontbench split itself was built to
# guard against - just baked into the dictionary this time instead of the
# role composition.
#
# NEW DICTIONARY built and piloted over 5 rounds (64t_king_dictionary_
# pilot.R, kept as the record of what was tried and rejected) against King
# (1981)'s own language on what career politicians DO (ambition, self-
# assertion, disputatiousness, restlessness) - NOT what they call their own
# job title. Key findings from piloting, in order:
#   - King's own third-person academic vocabulary ("restlessness",
#     "self-assertiveness", "wilful") essentially never occurs in real
#     speech (8/10 round-1 categories scored ZERO across 2m sampled words).
#   - Natural-language paraphrases of the same constructs do occur, but far
#     more sparsely than office-reference language (~80 clean hits per 2m
#     words here vs 201 for the old dictionary on the same sample).
#   - Two phrases that looked productive were actually contaminated: "make
#     a real difference" and "hold the government to account" are routine
#     policy/scrutiny rhetoric any MP uses, not self-regard - dropped.
#   - Naked personal-ambition phrasing ("I want to be remembered", "I want
#     to lead") NEVER occurs - a real, substantive finding (institutional
#     self-effacement norm), not a dictionary-design failure - so this
#     whole vein was abandoned.
#   - The one genuinely productive vein beyond the original candidates:
#     VOLITIONAL first-person "I want/wish/hope to..." constructions -
#     distinct from the already-excluded EPISTEMIC "I think/I believe/in my
#     view/I feel" markers (those state a belief, these assert a personal
#     will) - PJ's own distinction, confirmed productive on testing.
#
# This is expected to be a SPARSER, NOISIER series than 64q's (real signal,
# ~40% the density) - that is the price of measuring something King
# describes as genuinely rare in the chamber's own register, not a defect
# in this script.
#
# METHOD: identical sampling/role-split logic to 64q (same seed, same
# filter, same speeches) - only the career_terms dictionary changes.
#
# OUTPUT: online_appendix/ch3_career_orientation_split_1979_2019.csv

suppressMessages({library(dplyr); library(readr); library(stringr); library(purrr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
DATA_IN   <- file.path(WKBD_ROOT, "sources_raw/blumenau_damiani_commons_speeches_1979_2019/extracted/out")

# FINAL dictionary, 11 Sep, after 5 pilot rounds (64t) - see header above.
career_terms <- c(
  # determination
  "i am determined to", "i am determined that", "i am committed to", "i will continue to fight",
  # volitional want (King p.281: "the self-image, the desire for positive accomplishment")
  "i want to see", "i would like to see", "i wish to see", "i hope to see", "i want the government to",
  "history will judge",
  # fundamental dispute (King p.285: "confident assertion of fundamentally different points of view")
  "i will vote against", "i fundamentally disagree", "i cannot vote for", "i part company with",
  # self-assertion (King p.279-280: self-assertiveness, "determined to exercise their own judgment")
  "i make no apology", "i am not prepared to", "i speak for myself", "i stand by what i have said",
  "no one will tell me",
  # backbench self-assertion outlet (King p.280: select committees / scrutiny)
  "hold ministers to account"
)
# UNCHANGED from 64q - this dictionary was never the problem, only career_terms was redesigned.
policy_terms <- c(
  "my constituents", "my constituency", "people in my",
  "the evidence", "the research shows", "the data",
  "the public", "communities", "families",
  "workers", "businesses", "this policy", "the policy",
  "the bill", "the legislation", "the government must",
  "we must", "we should", "we need to"
)
score_speech <- function(text, terms) {
  text_lower <- tolower(text)
  sum(str_count(text_lower, fixed(terms)))
}

years <- 1979:2019
results <- vector("list", length(years))

for (i in seq_along(years)) {
  yr <- years[i]
  f <- file.path(DATA_IN, sprintf("%d.csv", yr))
  if (!file.exists(f)) next

  d <- read_csv(f, show_col_types = FALSE, progress = FALSE,
                col_select = c(hdate, body, n_words, holds_government_position, holds_opposition_position)) |>
    filter(!is.na(body), nchar(body) > 300)

  set.seed(42)
  samp <- d |> slice_sample(n = min(1500, nrow(d)))  # SAME sample as 64q/64n, same seed

  scored <- samp |>
    mutate(
      n_words_calc = str_count(body, "\\S+"),
      n_career   = map_int(body, score_speech, career_terms),
      n_policy   = map_int(body, score_speech, policy_terms),
      is_frontbench = coalesce(holds_government_position, FALSE) | coalesce(holds_opposition_position, FALSE)
    ) |>
    filter(n_words_calc >= 50)

  # AGGREGATE-THEN-RATIO, not mean-of-per-speech-ratios (fixed 11 Sep): with
  # this sparse dictionary, mean n_career/speech is ~0.009 vs ~1.18 for
  # n_policy - 99%+ of individual speeches have n_career=0, so a per-speech
  # ratio is swamped by the +0.5 smoothing constant and just tracks
  # n_policy noise, not the career dictionary at all (confirmed: the old
  # per-speech-average method gave period means within ~1pp of the OLD
  # office-reference dictionary's numbers, despite a completely different
  # word list - a tell that it wasn't measuring the new dictionary). Summing
  # hits across the whole group before taking one ratio lets the real,
  # sparse signal through.
  by_group <- scored |>
    group_by(is_frontbench) |>
    summarise(n = n(), n_career_sum = sum(n_career), n_policy_sum = sum(n_policy),
              ratio = (sum(n_career) + 0.5) / (sum(n_career) + sum(n_policy) + 1), .groups = "drop")

  bb <- by_group |> filter(!is_frontbench)
  fb <- by_group |> filter(is_frontbench)

  results[[i]] <- tibble(
    year = yr,
    n_backbench = if (nrow(bb) > 0) bb$n else NA_integer_,
    backbench_ratio = if (nrow(bb) > 0) bb$ratio else NA_real_,
    n_frontbench = if (nrow(fb) > 0) fb$n else NA_integer_,
    frontbench_ratio = if (nrow(fb) > 0) fb$ratio else NA_real_,
    backbench_n_career_sum = if (nrow(bb) > 0) bb$n_career_sum else NA_integer_,
    frontbench_n_career_sum = if (nrow(fb) > 0) fb$n_career_sum else NA_integer_,
    backbench_n_policy_sum = if (nrow(bb) > 0) bb$n_policy_sum else NA_integer_,
    frontbench_n_policy_sum = if (nrow(fb) > 0) fb$n_policy_sum else NA_integer_,
    n_career_hits = sum(scored$n_career)
  )
}

annual <- bind_rows(results) |> arrange(year)

cat("\n=== PERIOD MEANS (career-orientation dictionary) ===\n")
period <- function(d, y0, y1, col) d |> filter(year >= y0, year <= y1) |> summarise(m = mean({{col}}, na.rm = TRUE)) |> pull(m)
for (rng in list(c(1979, 1988), c(1989, 1997), c(1998, 2009), c(2010, 2019))) {
  bb_p <- period(annual, rng[1], rng[2], backbench_ratio)
  fb_p <- period(annual, rng[1], rng[2], frontbench_ratio)
  cat(sprintf("%d-%d: Backbench %.1f%%  |  Frontbench %.1f%%  |  Frontbench premium %+.1fpp\n",
              rng[1], rng[2], bb_p*100, fb_p*100, (fb_p-bb_p)*100))
}
cat("\nTotal career-term hits, 1979-2019 sample:", sum(annual$n_career_hits, na.rm = TRUE), "\n")

OUT <- file.path(WKBD_ROOT, "online_appendix/ch3_career_orientation_split_1979_2019.csv")
dir.create(dirname(OUT), showWarnings = FALSE)
write_csv(annual |> select(-n_career_hits), OUT)
cat("Saved:", OUT, "\n")
